-- Revised estimates are current operational metadata; purchased line promises stay immutable.
-- Only date, staff ownership and check time enter history. Private check notes stay on the order.
CREATE TRIGGER IF NOT EXISTS audit_order_preorder_plan_update AFTER UPDATE ON orders
WHEN json_object('Revised dispatch date',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate'))<=10 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate') ELSE NULL END,'Estimate owner',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner'))<=320 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner') ELSE NULL END,'Estimate checked at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.confirmedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.confirmedAt') ELSE NULL END) IS NOT json_object('Revised dispatch date',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate'))<=10 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate') ELSE NULL END,'Estimate owner',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner'))<=320 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner') ELSE NULL END,'Estimate checked at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.confirmedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.confirmedAt') ELSE NULL END)
OR json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.note') IS NOT json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.note')
BEGIN
 INSERT INTO change_events(id,occurred_at,recorded_at,source,actor,actor_type,action,entity_type,entity_id,summary,status,changes)
 VALUES(lower(hex(randomblob(16))),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),
 COALESCE((SELECT source FROM change_context WHERE id=1),'system'),COALESCE((SELECT actor FROM change_context WHERE id=1),'Unattributed database change'),COALESCE((SELECT actor_type FROM change_context WHERE id=1),'unknown'),COALESCE((SELECT action FROM change_context WHERE id=1),'order.preorder_plan.update'),'order',CAST(NEW.id AS TEXT),COALESCE((SELECT summary FROM change_context WHERE id=1),'Current preorder estimate updated'),'succeeded',
 (SELECT json_group_array(json_object('field',a.key,'before',a.value,'after',b.value)) FROM json_each(json_object('Revised dispatch date',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate'))<=10 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.dispatchDate') ELSE NULL END,'Estimate owner',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner')='text' AND length(json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner'))<=320 THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.owner') ELSE NULL END,'Estimate checked at',CASE WHEN json_type(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.confirmedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(OLD.data) THEN OLD.data ELSE '{}' END,'$.preorderPlan.confirmedAt') ELSE NULL END)) a JOIN json_each(json_object('Revised dispatch date',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate'))<=10 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.dispatchDate') ELSE NULL END,'Estimate owner',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner')='text' AND length(json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner'))<=320 THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.owner') ELSE NULL END,'Estimate checked at',CASE WHEN json_type(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.confirmedAt') IN ('integer','real') THEN json_extract(CASE WHEN json_valid(NEW.data) THEN NEW.data ELSE '{}' END,'$.preorderPlan.confirmedAt') ELSE NULL END)) b ON a.key=b.key WHERE a.value IS NOT b.value));
END;
